struct Temperature {
    let celsius: Double
    init(celsius: Double) { self.celsius = celsius }
    init?(fahrenheit: Double) {                       // named by label, failable
        guard fahrenheit >= -459.67 else { return nil }
        self.celsius = (fahrenheit - 32) * 5 / 9
    }
}
// if let t = Temperature(fahrenheit: 451) { print(t.celsius) }

