struct Temperature {
    let celsius: Double
    static func make(fahrenheit: Double) -> Temperature? {   // memberwise init stays synthesized
        guard fahrenheit >= -459.67 else { return nil }
        return Temperature(celsius: (fahrenheit - 32) * 5 / 9)
    }
}
